package com.pranit.productsupport.core.service;
import static org.junit.jupiter.api.Assertions.*;import com.pranit.productsupport.contracts.TicketStatus;import org.junit.jupiter.api.Test;
class TicketStatusPolicyTest {@Test void allowsValidTransitions(){assertTrue(TicketStatusPolicy.canTransition(TicketStatus.OPEN,TicketStatus.IN_REVIEW));assertTrue(TicketStatusPolicy.canTransition(TicketStatus.RESOLVED,TicketStatus.CLOSED));assertTrue(TicketStatusPolicy.canTransition(TicketStatus.RESOLVED,TicketStatus.IN_REVIEW));}@Test void rejectsInvalidAndTerminalTransitions(){assertFalse(TicketStatusPolicy.canTransition(TicketStatus.OPEN,TicketStatus.CLOSED));assertFalse(TicketStatusPolicy.canTransition(TicketStatus.CLOSED,TicketStatus.IN_REVIEW));assertFalse(TicketStatusPolicy.canTransition(TicketStatus.REJECTED,TicketStatus.OPEN));}}
